{
  "cases": [
    {
      "id": "C1",
      "instrument_review": "MESA distinguishes evidence of repeated testing from evidence of stable results. Neither is established by one reported run with repetition unspecified.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing reporting does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish stability across runs."
        }
      ]
    },
    {
      "id": "C2",
      "instrument_review": "Under MESA, the explicit single evaluation rules out repeated testing. It leaves score stability unknown.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "The passage explicitly states that no repeated evaluation occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it.",
          "reason": "A single evaluation supplies no evidence of score variation across runs."
        }
      ]
    },
    {
      "id": "C3",
      "instrument_review": "MESA supports both repeated testing and stability within the report's stated criterion, limited to the tested system and conditions.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluations under identical stated conditions measured score changes."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The observed range meets the stated stability criterion."
        }
      ]
    },
    {
      "id": "C4",
      "instrument_review": "MESA separates whether testing occurred from whether its findings were favourable. Repeated testing occurred, but the results fail the stated stability criterion.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The passage explicitly reports repeated testing under identical stated conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%. The report defines stable for this comparison as a range of at most two percentage points.",
          "reason": "The observed variation exceeds the report's stability threshold."
        }
      ]
    },
    {
      "id": "C5",
      "instrument_review": "MESA treats installation documentation as relevant to access and reproducibility, but it supplies no additional evidence of repeated testing or score stability.",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "The installation instructions do not resolve whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added documentation provides no evidence of stability across runs."
        }
      ]
    },
    {
      "id": "C6",
      "instrument_review": "MESA supports the observed comparison on the evaluated grid puzzles. Evidence for general intelligence across domains is absent.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A solved more of the evaluated puzzles under the stated scoring and instructions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The findings do not establish a comparison of general intelligence across domains."
        }
      ]
    },
    {
      "id": "C7",
      "instrument_review": "MESA identifies a gap between the intended selection use and the evidence. The grid comparison is supported, but the broader intended use is not established.",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The observed results favour A on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Stating a general-intelligence selection purpose does not provide evidence across domains."
        }
      ]
    },
    {
      "id": "C8",
      "instrument_review": "MESA distinguishes initial benchmark scores from later evidence on the intended use. The trial supports decision correctness in the studied workshop; safety and time outcomes remain unmeasured.",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "Those scores alone do not establish improved real workshop decisions; later evidence cannot be attributed to the initial scores."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%. The reported uncertainty interval for the difference was 12 to 28 percentage points.",
          "reason": "The randomized trial and reported interval support better correctness with A in the studied workshop and conditions."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Decision correctness results do not establish a safety improvement when safety was unmeasured."
        }
      ]
    }
  ],
  "closing_note": "No instructions required clarification. Missing evidence was treated as insufficient information, not as proof of failure."
}
